  ///  Which attainment this was, one-based.
  public var ATTAINED_OCCURRENCE: UInt32 { let o = _accessor.offset(VT.ATTAINED_OCCURRENCE); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
