    PCEStopReport.addVectorOf(SYNCHRONIZED_STATES: SYNCHRONIZED_STATES, &fbb)
    PCEStopReport.add(SAMPLE: SAMPLE, &fbb)
    PCEStopReport.add(FUNCTION_EVALUATION_COUNT: FUNCTION_EVALUATION_COUNT, &fbb)
